import{_ as a,c as r,o as t,a2 as i}from"./chunks/framework.mqLGQ42V.js";const _=JSON.parse('{"title":"市场概览 (Marketplace Overview) - Rive 社区","description":"社区 (Community) Rive 市场 (Marketplace) 是一个创作者可以分享文件、获取反馈，并通过直接在 Rive 编辑器中打开他人的文件来学习的地方。","frontmatter":{"title":"市场概览 (Marketplace Overview) - Rive 社区","description":"社区 (Community) Rive 市场 (Marketplace) 是一个创作者可以分享文件、获取反馈，并通过直接在 Rive 编辑器中打开他人的文件来学习的地方。","head":[["meta",{"name":"keywords","content":"Rive, Rive 中文文档, Rive 社区, 市场概览"}]]},"headers":[],"relativePath":"community/marketplace-overview.md","filePath":"community/marketplace-overview.md","lastUpdated":1774867914000}'),o={name:"community/marketplace-overview.md"};function l(p,e,m,n,c,v){return t(),r("div",null,[...e[0]||(e[0]=[i('<p>社区 (Community)</p><h1 id="市场概览-marketplace-overview" tabindex="-1">市场概览 (Marketplace Overview) <a class="header-anchor" href="#市场概览-marketplace-overview" aria-label="Permalink to &quot;市场概览 (Marketplace Overview)&quot;">​</a></h1><p>Rive 市场 (Marketplace) 是一个创作者可以分享文件、获取反馈，并通过直接在 Rive 编辑器中打开他人的文件来学习的地方。 市场中的所有文件均在 <a href="https://creativecommons.org/licenses/by/4.0/" target="_blank" rel="noreferrer">CC BY</a> 许可证下共享。</p><h2 id="​-混音-remixing" tabindex="-1"><a href="#remixing">​</a> 混音 (Remixing) <a class="header-anchor" href="#​-混音-remixing" aria-label="Permalink to &quot;[​](#remixing) 混音 (Remixing)&quot;">​</a></h2><p>混音 (Remix) 是对另一位用户文件的复制。它以他们的文件作为你账户中新文件的起点。混音鼓励分享，你可能还会学到一些新技巧！</p><p>要从市场混音一个文件：</p><ol><li>找到你喜欢的文件</li><li>点击缩略图</li><li>使用右侧的&quot;混音&quot;按钮</li></ol><blockquote><p><em>[原文档演示图由于官方服务器迁移已失效]</em> (描述: 混音按钮示例)</p></blockquote><p>文件将在编辑器中打开，并且会在你的文件浏览器中添加一个新副本。</p><p><a href="https://help.rive.app/community/community-overview" target="_blank" rel="noreferrer">社区概览 (Community Overview)</a><a href="https://help.rive.app/community/rive-experts" target="_blank" rel="noreferrer">Rive 专家 (Rive Experts)</a></p>',10)])])}const k=a(o,[["render",l]]);export{_ as __pageData,k as default};
